60	int esp_graphics_check_buffer(FAR const struct esp_graphics_buffer_s *buffer,
61	                              uint32_t x, uint32_t y,
62	                              uint32_t width, uint32_t height)
63	{
64	  uintptr_t address = (uintptr_t)buffer->data;
65	  uintptr_t last;
66	  int ret = esp_graphics_buffer_bounds(buffer, x, y, width, height);
67	
68	  if (ret < 0)
69	    {
70	      return ret;
71	    }
72	
73	  last = address + buffer->size - 1;
74	  if (!((esp_ptr_dma_capable((void *)address) &&
75	         esp_ptr_dma_capable((void *)last)) ||
76	        (esp_ptr_external_ram((void *)address) &&
77	         esp_ptr_external_ram((void *)last))))
78	    {
79	      return -EFAULT;
80	    }
81	
82	  return OK;
83	}
