115	static void esp_graphics_reset(void)
116	{
117	  unsigned int channel;
118	
119	  /* This port exclusively owns DMA2D.  A peripheral reset also quiesces
120	   * stalled AXI requests before buffers can be returned to the caller.
121	   */
122	
123	#ifdef CONFIG_ESP32P4_PPA
124	  esp_ppa_reset();
125	#endif
126	  PERIPH_RCC_ATOMIC()
127	    {
128	      dma2d_ll_reset_register(0);
129	    }
130	
131	  dma2d_ll_hw_enable(DMA2D_LL_GET_HW(0), true);
132	  for (channel = 0; channel < 2; channel++)
133	    {
134	      dma2d_ll_tx_enable_interrupt(DMA2D_LL_GET_HW(0), channel,
135	                                   DMA2D_LL_TX_EVENT_MASK, false);
136	      dma2d_ll_tx_clear_interrupt_status(DMA2D_LL_GET_HW(0), channel,
137	                                         DMA2D_LL_TX_EVENT_MASK);
138	    }
139	
140	  dma2d_ll_rx_enable_interrupt(DMA2D_LL_GET_HW(0), 0,
141	                               DMA2D_LL_RX_EVENT_MASK, false);
142	  dma2d_ll_rx_clear_interrupt_status(DMA2D_LL_GET_HW(0), 0,
143	                                     DMA2D_LL_RX_EVENT_MASK);
144	}
