23	static ppa_srm_color_mode_t esp_ppa_format(enum esp_graphics_format_e format)
24	{
25	  switch (format)
26	    {
27	      case ESP_GRAPHICS_RGB565:
28	        return PPA_SRM_COLOR_MODE_RGB565;
29	      case ESP_GRAPHICS_RGB888:
30	        return PPA_SRM_COLOR_MODE_RGB888;
31	      case ESP_GRAPHICS_ARGB8888:
32	        return PPA_SRM_COLOR_MODE_ARGB8888;
33	      default:
34	        return PPA_SRM_COLOR_MODE_YUV422_UYVY;
35	    }
36	}
