38	void esp_ppa_reset(void)
39	{
40	  PERIPH_RCC_ATOMIC()
41	    {
42	      ppa_ll_enable_bus_clock(true);
43	      ppa_ll_reset_register();
44	    }
45	
46	  /* PPA EOF precedes DMA writeback; only DMA EOF returns buffer ownership.
47	   * Parameter errors use PPA's own interrupt to avoid a stalled DMA timeout.
48	   */
49	
50	  (PPA_LL_GET_HW)->int_clr.val = 0x0f;
51	  (PPA_LL_GET_HW)->int_ena.val = PPA_SR_PARAM_CFG_ERR_INT_ENA |
52	                             PPA_BLEND_PARAM_CFG_ERR_INT_ENA;
53	}
54	
55	uint32_t esp_ppa_errors(void)
56	{
57	  uint32_t status = (PPA_LL_GET_HW)->int_st.val;
58	
59	  (PPA_LL_GET_HW)->int_clr.val = status;
60	  return status;
61	}
62	
63	void esp_ppa_uninitialize(void)
64	{
65	  (PPA_LL_GET_HW)->int_ena.val = 0;
66	  PERIPH_RCC_ATOMIC()
67	    {
68	      ppa_ll_enable_bus_clock(false);
69	    }
70	}
