72	int esp_ppa_validate(FAR const struct esp_graphics_job_s *job)
73	{
74	  uint32_t width = job->width;
75	  uint32_t height = job->height;
76	  int ret;
77	
78	  if (job->operation != ESP_GRAPHICS_FILL &&
79	      job->operation != ESP_GRAPHICS_SRM &&
80	      job->operation != ESP_GRAPHICS_BLEND)
81	    {
82	      return -ENOTSUP;
83	    }
84	
85	  if (job->operation != ESP_GRAPHICS_FILL)
86	    {
87	      ret = esp_graphics_check_buffer(&job->src, job->src_x, job->src_y,
88	                                      width, height);
89	      if (ret < 0)
90	        {
91	          return ret;
92	        }
93	    }
94	
95	  if (job->operation == ESP_GRAPHICS_SRM)
96	    {
97	      if (job->scale_x_q4 == 0 || job->scale_y_q4 == 0 ||
98	          job->scale_x_q4 >= PPA_LL_SRM_SCALING_INT_MAX * 16 ||
99	          job->scale_y_q4 >= PPA_LL_SRM_SCALING_INT_MAX * 16 ||
100	          (job->rotation != 0 && job->rotation != 90 &&
101	           job->rotation != 180 && job->rotation != 270))
102	        {
103	          return -EINVAL;
104	        }
105	
106	      width = (uint32_t)job->width * job->scale_x_q4 / 16;
107	      height = (uint32_t)job->height * job->scale_y_q4 / 16;
108	      if (job->rotation == 90 || job->rotation == 270)
109	        {
110	          uint32_t temporary = width;
111	          width = height;
112	          height = temporary;
113	        }
114	
115	      /* YUV output has additional per-macroblock chroma restrictions.
116	       * The first port supports YUV422 input to RGB, and RGB conversions.
117	       */
118	
119	      if (job->dst.format == ESP_GRAPHICS_YUV422)
120	        {
121	          return -ENOTSUP;
122	        }
123	    }
124	
125	  if (job->operation == ESP_GRAPHICS_BLEND)
126	    {
127	      if (job->src.format == ESP_GRAPHICS_YUV422 ||
128	          job->foreground.format == ESP_GRAPHICS_YUV422 ||
129	          job->dst.format == ESP_GRAPHICS_YUV422)
130	        {
131	          return -ENOTSUP;
132	        }
133	
134	      ret = esp_graphics_check_buffer(&job->foreground, job->fg_x, job->fg_y,
135	                                      width, height);
136	      if (ret < 0)
137	        {
138	          return ret;
139	        }
140	    }
141	
142	  if (job->operation == ESP_GRAPHICS_FILL &&
143	      job->dst.format == ESP_GRAPHICS_YUV422)
144	    {
145	      return -ENOTSUP;
146	    }
147	
148	  if (job->operation == ESP_GRAPHICS_SRM && (width < 2 || height < 2))
149	    {
150	      return -ENOTSUP;
151	    }
152	
153	  return esp_graphics_check_buffer(&job->dst, job->dst_x, job->dst_y,
154	                                   width, height);
155	}
