157	static void esp_ppa_srm(FAR struct esp_graphics_s *priv)
158	{
159	  FAR const struct esp_graphics_job_s *job = &priv->job;
160	  FAR ppa_dev_t *dev = PPA_LL_GET_HW;
161	  ppa_srm_color_mode_t src = esp_ppa_format(job->src.format);
162	  ppa_srm_color_mode_t dst = esp_ppa_format(job->dst.format);
163	  uint32_t block_h;
164	  uint32_t block_v;
165	  uint32_t out_w = (uint32_t)job->width * job->scale_x_q4 / 16;
166	  uint32_t divisor = esp_graphics_bpp(job->dst.format) >= 3 ? 32 : 64;
167	  uint32_t left_w = out_w % divisor;
168	  uint32_t left_h = job->height % 16;
169	  bool bypass;
170	
171	  esp_graphics_descriptor(&priv->tx[0].dma, &job->src,
172	                           job->src_x, job->src_y, job->width, job->height);
173	  esp_graphics_descriptor(&priv->rx[0].dma, &job->dst,
174	                           job->dst_x, job->dst_y, 2, 2);
175	  esp_graphics_tx(0, DMA2D_TRIG_PERIPH_PPA_SRM,
176	                   SOC_DMA2D_TRIG_PERIPH_PPA_SRM_TX, &priv->tx[0].dma);
177	  esp_graphics_rx(DMA2D_TRIG_PERIPH_PPA_SRM,
178	                   SOC_DMA2D_TRIG_PERIPH_PPA_SRM_RX, &priv->rx[0].dma);
179	
180	  ppa_ll_srm_set_mb_size(dev, PPA_LL_SRM_MB_SIZE_16_16);
181	  ppa_ll_srm_get_dma_dscr_port_mode_block_size(dev, src,
182	                                              PPA_LL_SRM_MB_SIZE_16_16,
183	                                              &block_h, &block_v);
184	  dma2d_ll_tx_set_dscr_port_block_size(DMA2D_LL_GET_HW(0), 0,
185	                                       block_h, block_v);
186	  dma2d_ll_tx_enable_dscr_port(DMA2D_LL_GET_HW(0), 0, true);
187	  ppa_ll_srm_set_rx_color_mode(dev, src);
188	  if (job->src.format == ESP_GRAPHICS_YUV422)
189	    {
190	      ppa_ll_srm_set_rx_yuv_range(dev, PPA_COLOR_RANGE_LIMIT);
191	      ppa_ll_srm_set_rx_yuv2rgb_std(dev, PPA_COLOR_CONV_STD_RGB_YUV_BT601);
192	    }
193	
194	  ppa_ll_srm_enable_rx_byte_swap(dev, false);
195	  ppa_ll_srm_enable_rx_rgb_swap(dev, false);
196	  ppa_ll_srm_configure_rx_alpha(dev, PPA_ALPHA_NO_CHANGE, 0);
197	  ppa_ll_srm_set_tx_color_mode(dev, dst);
198	  ppa_ll_srm_set_rotation_angle(dev, job->rotation / 90);
199	  ppa_ll_srm_set_scaling_x(dev, job->scale_x_q4 / 16, job->scale_x_q4 % 16);
200	  ppa_ll_srm_set_scaling_y(dev, job->scale_y_q4 / 16, job->scale_y_q4 % 16);
201	  ppa_ll_srm_enable_mirror_x(dev, job->mirror_x);
202	  ppa_ll_srm_enable_mirror_y(dev, job->mirror_y);
203	
204	  /* DIG-734: preserve the pinned HAL's small-tail macroblock workaround. */
205	
206	  left_w = left_w == 0 ? divisor : left_w;
207	  left_h = left_h == 0 ? 16 : left_h;
208	  left_h = left_h * job->scale_y_q4 / 16;
209	  bypass = (out_w > divisor || job->height > 16) &&
210	           left_w * left_h * esp_graphics_bpp(job->dst.format) * 8 < 1536;
211	  ppa_ll_srm_bypass_mb_order(dev, bypass);
212	}
