214	static void esp_ppa_blend(FAR struct esp_graphics_s *priv)
215	{
216	  FAR const struct esp_graphics_job_s *job = &priv->job;
217	  FAR ppa_dev_t *dev = PPA_LL_GET_HW;
218	  color_pixel_rgb888_data_t low;
219	  color_pixel_rgb888_data_t high;
220	
221	  low.val = 0;
222	  high.val = 0xffffff;
223	
224	  esp_graphics_descriptor(&priv->tx[0].dma, &job->src,
225	                           job->src_x, job->src_y, job->width, job->height);
226	  esp_graphics_descriptor(&priv->fg->dma, &job->foreground,
227	                           job->fg_x, job->fg_y, job->width, job->height);
228	  esp_graphics_tx(0, DMA2D_TRIG_PERIPH_PPA_BLEND,
229	                   SOC_DMA2D_TRIG_PERIPH_PPA_BLEND_BG_TX, &priv->tx[0].dma);
230	  esp_graphics_tx(1, DMA2D_TRIG_PERIPH_PPA_BLEND,
231	                   SOC_DMA2D_TRIG_PERIPH_PPA_BLEND_FG_TX, &priv->fg->dma);
232	  ppa_ll_blend_set_rx_bg_color_mode(dev, esp_ppa_format(job->src.format));
233	  ppa_ll_blend_set_rx_fg_color_mode(dev,
234	                                    esp_ppa_format(job->foreground.format));
235	  ppa_ll_blend_enable_rx_bg_rgb_swap(dev, false);
236	  ppa_ll_blend_enable_rx_fg_rgb_swap(dev, false);
237	  ppa_ll_blend_enable_rx_bg_byte_swap(dev, false);
238	  ppa_ll_blend_enable_rx_fg_byte_swap(dev, false);
239	  ppa_ll_blend_configure_rx_bg_alpha(dev, job->bg_pixel_alpha ?
240	                                     PPA_ALPHA_NO_CHANGE :
241	                                     PPA_ALPHA_FIX_VALUE,
242	                                     job->bg_alpha);
243	  ppa_ll_blend_configure_rx_fg_alpha(dev, job->fg_pixel_alpha ?
244	                                     PPA_ALPHA_NO_CHANGE :
245	                                     PPA_ALPHA_FIX_VALUE,
246	                                     job->fg_alpha);
247	  ppa_ll_blend_configure_rx_bg_ck_range(dev, &high, &low);
248	  ppa_ll_blend_configure_rx_fg_ck_range(dev, &high, &low);
249	  ppa_ll_blend_set_ck_default_rgb(dev, &low);
250	  ppa_ll_blend_enable_ck_fg_bg_reverse(dev, false);
251	}
