328	static int esp_graphics_validate(FAR const struct esp_graphics_job_s *job)
329	{
330	  int ret;
331	
332	  if (job->operation != ESP_GRAPHICS_COPY)
333	    {
334	#ifdef CONFIG_ESP32P4_PPA
335	      ret = esp_ppa_validate(job);
336	#else
337	      ret = -ENOTSUP;
338	#endif
339	    }
340	  else
341	    {
342	      if (job->src.format != ESP_GRAPHICS_RGB565 ||
343	          job->dst.format != ESP_GRAPHICS_RGB565 ||
344	          job->height > ESP_GRAPHICS_DESCRIPTORS * ESP_GRAPHICS_BAND_ROWS)
345	        {
346	          return -ENOTSUP;
347	        }
348	
349	      ret = esp_graphics_check_buffer(&job->src, job->src_x, job->src_y,
350	                                      job->width, job->height);
351	      if (ret == OK)
352	        {
353	          ret = esp_graphics_check_buffer(&job->dst, job->dst_x, job->dst_y,
354	                                          job->width, job->height);
355	        }
356	    }
357	
358	  if (ret < 0)
359	    {
360	      return ret;
361	    }
362	
363	  if ((job->operation != ESP_GRAPHICS_FILL &&
364	       esp_graphics_overlap(&job->src, &job->dst)) ||
365	      (job->operation == ESP_GRAPHICS_BLEND &&
366	       esp_graphics_overlap(&job->foreground, &job->dst)))
367	    {
368	      return -EINVAL;
369	    }
370	
371	  return OK;
372	}
