61	static void secure_clear(void *memory, size_t size)
62	{
63	    volatile unsigned char *p = memory;
64	    while (p && size-- > 0u) *p++ = 0u;
65	}
66	
67	static void model_state_destroy(smart_home_model_state_t *state)
68	{
69	    if (!state) return;
70	    secure_clear(state->request, state->request_size);
71	    secure_clear(state->response, state->response_size);
72	    secure_clear(state->decoded, CONFIG_SMART_HOME_MODEL_DECODED_BUFFER_SIZE);
73	    smart_home_bulk_free(state->request);
74	    smart_home_bulk_free(state->response);
75	    smart_home_bulk_free(state->decoded);
76	    secure_clear(state, sizeof(*state));
77	    smart_home_bulk_free(state);
78	}
