80	static int validate_config(const smart_home_model_config_t *config)
81	{
82	    const char *p;
83	    unsigned long port;
84	
85	    if (!config || !memchr(config->host, '\0', sizeof(config->host)) ||
86	        !memchr(config->path, '\0', sizeof(config->path)) ||
87	        !memchr(config->port, '\0', sizeof(config->port)) ||
88	        !memchr(config->model, '\0', sizeof(config->model)) ||
89	        !memchr(config->api_key, '\0', sizeof(config->api_key)) ||
90	        !config->host[0] || config->path[0] != '/' || !config->port[0] ||
91	        !config->model[0] || config->timeout_ms < 5000 ||
92	        config->timeout_ms > 60000) return AGENT_ERROR_INVALID;
93	
94	    for (p = config->host; *p; p++) {
95	        if (!isalnum((unsigned char)*p) && *p != '.' && *p != '-')
96	            return AGENT_ERROR_INVALID;
97	    }
98	    for (p = config->port; *p; p++) {
99	        if (!isdigit((unsigned char)*p)) return AGENT_ERROR_INVALID;
100	    }
101	    port = strtoul(config->port, NULL, 10);
102	    if (port == 0u || port > 65535u) return AGENT_ERROR_INVALID;
103	    if (config->request_buffer_size == 0u || config->response_buffer_size == 0u ||
104	        config->request_buffer_size > CONFIG_SMART_HOME_MODEL_REQUEST_BUFFER_SIZE ||
105	        config->response_buffer_size > CONFIG_SMART_HOME_MODEL_RESPONSE_BUFFER_SIZE)
106	        return AGENT_ERROR_CAPACITY;
107	    return AGENT_OK;
108	}
