110	static int model_state_create(smart_home_agent_backend_t *backend,
111	                              const smart_home_model_config_t *config,
112	                              smart_home_model_state_t **out)
113	{
114	    smart_home_model_state_t *state;
115	    agent_openai_config_t provider = {0};
116	    int n;
117	    int ret = validate_config(config);
118	
119	    *out = NULL;
120	    if (ret != AGENT_OK) return ret;
121	    state = smart_home_bulk_alloc(sizeof(*state));
122	    if (!state) return AGENT_ERROR_NOMEM;
123	    memset(state, 0, sizeof(*state));
124	    state->request_size = config->request_buffer_size;
125	    state->response_size = config->response_buffer_size;
126	    state->request = smart_home_bulk_alloc(state->request_size);
127	    state->response = smart_home_bulk_alloc(state->response_size);
128	    state->decoded = smart_home_bulk_alloc(CONFIG_SMART_HOME_MODEL_DECODED_BUFFER_SIZE);
129	    if (!state->request || !state->response || !state->decoded) {
130	        ret = AGENT_ERROR_NOMEM;
131	        goto fail;
132	    }
133	    n = snprintf(state->endpoint, sizeof(state->endpoint), "https://%s:%s%s",
134	                 config->host, config->port, config->path);
135	    if (n < 0 || (size_t)n >= sizeof(state->endpoint)) {
136	        ret = AGENT_ERROR_LIMIT;
137	        goto fail;
138	    }
139	    memcpy(state->model, config->model, strlen(config->model) + 1u);
140	    if (config->api_key[0]) {
141	        n = snprintf(state->authorization, sizeof(state->authorization),
142	                     "Bearer %s", config->api_key);
143	        if (n < 0 || (size_t)n >= sizeof(state->authorization)) {
144	            ret = AGENT_ERROR_LIMIT;
145	            goto fail;
146	        }
147	    }
148	
149	    provider.transport = backend->transport;
150	    provider.runtime = backend->runtime;
151	    provider.endpoint = agent_string_view(state->endpoint, strlen(state->endpoint));
152	    provider.model = agent_string_view(state->model, strlen(state->model));
153	    provider.authorization = agent_string_view(state->authorization,
154	                                                strlen(state->authorization));
155	    provider.use_legacy_max_tokens = true;
156	    provider.request_buffer = state->request;
157	    provider.request_capacity = state->request_size;
158	    provider.response_buffer = state->response;
159	    provider.response_capacity = state->response_size;
160	    provider.decoded_buffer = state->decoded;
161	    provider.decoded_capacity = CONFIG_SMART_HOME_MODEL_DECODED_BUFFER_SIZE;
162	    provider.response_token_capacity = CONFIG_SMART_HOME_MODEL_JSON_TOKENS;
163	    provider.max_response_header_bytes = sizeof(backend->response_header_text);
164	    provider.max_json_depth = AGENT_MAX_JSON_DEPTH;
165	    ret = agent_openai_provider_init(&state->provider, &provider);
166	    if (ret != AGENT_OK) goto fail;
167	    *out = state;
168	    return AGENT_OK;
169	
170	fail:
171	    model_state_destroy(state);
172	    return ret;
173	}
