175	static agent_error_t model_complete(void *context,
176	                                    const agent_model_request_t *request,
177	                                    const agent_model_sink_t *sink)
178	{
179	    smart_home_agent_backend_t *backend = context;
180	    if (!backend->active || !backend->active->authorization[0])
181	        return AGENT_ERROR_AUTH;
182	    return agent_openai_model_ops()->complete(&backend->active->provider,
183	                                               request, sink);
184	}
