186	int smart_home_agent_backend_apply(smart_home_agent_backend_t *backend,
187	                                   const smart_home_model_config_t *config)
188	{
189	    smart_home_model_state_t *replacement;
190	    smart_home_model_state_t *previous;
191	    agent_limits_t limits;
192	    int ret;
193	
194	    if (!backend || !backend->agent) return AGENT_ERROR_INVALID;
195	    ret = model_state_create(backend, config, &replacement);
196	    if (ret != AGENT_OK) return ret;
197	    limits = backend->limits;
198	    limits.timeout_ms = (uint32_t)config->timeout_ms;
199	    limits.per_model_timeout_ms = (uint32_t)config->timeout_ms;
200	    if (config->max_output_tokens) limits.max_output_tokens = config->max_output_tokens;
201	    ret = agent_set_limits(backend->agent, &limits);
202	    if (ret != AGENT_OK) {
203	        model_state_destroy(replacement);
204	        return ret;
205	    }
206	    previous = backend->active;
207	    backend->active = replacement;
208	    backend->limits = limits;
209	    backend->transport_state.config.request_timeout_ms = (uint32_t)config->timeout_ms;
210	    backend->tls.config.io_timeout_ms = (uint32_t)config->timeout_ms;
211	    model_state_destroy(previous);
212	    return AGENT_OK;
213	}
