215	int smart_home_agent_backend_create(smart_home_agent_backend_t **out,
216	                                    agent_t **agent,
217	                                    const char *system_prompt,
218	                                    const smart_home_model_config_t *config)
219	{
220	    smart_home_agent_backend_t *backend = NULL;
221	    agent_port_openvela_tls_config_t tls = {0};
222	    agent_port_openvela_transport_config_t transport = {0};
223	    agent_config_t core = agent_config_default();
224	    const agent_model_ops_t model = {.complete = model_complete};
225	    const char *stage = "config";
226	    int ret;
227	
228	    if (!out || !agent || !system_prompt) return AGENT_ERROR_INVALID;
229	    *out = NULL;
230	    *agent = NULL;
231	    ret = validate_config(config);
232	    if (ret != AGENT_OK) goto fail;
233	    stage = "allocation";
234	    backend = smart_home_bulk_alloc(sizeof(*backend));
235	    if (!backend) {
236	        ret = AGENT_ERROR_NOMEM;
237	        goto fail;
238	    }
239	    memset(backend, 0, sizeof(*backend));
240	    core.limits.max_history_turns = CONFIG_SMART_HOME_SESSION_HISTORY_TURNS;
241	    backend->limits = core.limits;
242	    stage = "runtime";
243	    ret = agent_port_openvela_runtime_init(&backend->runtime);
244	    if (ret != AGENT_OK) goto fail;
245	    stage = "tls";
246	    tls.io_timeout_ms = (uint32_t)config->timeout_ms;
247	    ret = agent_port_openvela_tls_init(&backend->tls, &tls);
248	    if (ret != AGENT_OK) goto fail;
249	    transport.runtime = backend->runtime;
250	    transport.tls_ops = backend->tls.ops;
251	    transport.tls_context = &backend->tls;
252	    transport.request_timeout_ms = (uint32_t)config->timeout_ms;
253	    transport.url_buffer = backend->url;
254	    transport.url_buffer_size = sizeof(backend->url);
255	    transport.request_header_buffer = backend->request_header_text;
256	    transport.request_header_buffer_size = sizeof(backend->request_header_text);
257	    transport.request_headers = backend->request_headers;
258	    transport.request_header_capacity = 16u;
259	    transport.io_buffer = backend->io;
260	    transport.io_buffer_size = sizeof(backend->io);
261	    transport.response_headers = backend->response_headers;
262	    transport.response_header_capacity = 16u;
263	    transport.response_header_buffer = backend->response_header_text;
264	    transport.response_header_buffer_size = sizeof(backend->response_header_text);
265	    stage = "transport";
266	    ret = agent_port_openvela_transport_init(&backend->transport,
267	                                             &backend->transport_state, &transport);
268	    if (ret != AGENT_OK) goto fail;
269	    core.runtime = backend->runtime;
270	    core.system_prompt = agent_string_view(system_prompt, strlen(system_prompt));
271	    stage = "core";
272	    ret = agent_init(&backend->agent, &backend->core_storage, &core);
273	    if (ret != AGENT_OK) goto fail;
274	    stage = "session";
275	    {
276	        agent_session_storage_t storage;
277	#ifdef CONFIG_SMART_HOME_SESSION_PERSIST
278	        ret = smart_home_session_open(&backend->persistent, &storage);
279	#else
280	        const agent_session_ram_config_t ram = {
281	            backend->turns, CONFIG_SMART_HOME_SESSION_HISTORY_TURNS + 1u,
282	            backend->messages, sizeof(backend->messages) / sizeof(backend->messages[0]),
283	            backend->calls, sizeof(backend->calls) / sizeof(backend->calls[0]),
284	            backend->session_payload, sizeof(backend->session_payload),
285	            backend->read_messages, AGENT_MAX_PROJECTED_MESSAGES,
286	            backend->read_calls, AGENT_MAX_PROJECTED_MESSAGES
287	        };
288	        ret = agent_session_ram_init(&backend->session, &ram);
289	        if (ret == AGENT_OK) ret = agent_session_ram_bind(&backend->session, &storage);
290	#endif
291	        if (ret == AGENT_OK) ret = agent_set_session_storage(backend->agent, &storage);
292	        if (ret != AGENT_OK) goto fail;
293	    }
294	    stage = "model-bind";
295	    ret = agent_model_init(&backend->model, &backend->model_storage,
296	                           &model, backend);
297	    if (ret != AGENT_OK) goto fail;
298	    ret = agent_set_model(backend->agent, backend->model);
299	    if (ret != AGENT_OK) goto fail;
300	    stage = "model-config";
301	    ret = smart_home_agent_backend_apply(backend, config);
302	    if (ret != AGENT_OK) goto fail;
303	    *agent = backend->agent;
304	    *out = backend;
305	    return AGENT_OK;
306	
307	fail:
308	    printf("[smart_home_init] stage=backend-%s ret=%d (%s)\n",
309	           stage, ret, agent_error_str((agent_error_t)ret));
310	    smart_home_agent_backend_destroy(&backend);
311	    return ret;
312	}
