329	int smart_home_agent_backend_prepare_turn(smart_home_agent_backend_t *backend)
330	{
331	#ifdef CONFIG_SMART_HOME_SESSION_PERSIST
332	    return backend ? smart_home_session_prepare(backend->persistent) : AGENT_ERROR_INVALID;
333	#else
334	    size_t keep = CONFIG_SMART_HOME_SESSION_HISTORY_TURNS;
335	    int ret;
336	    if (!backend) return AGENT_ERROR_INVALID;
337	    ret = agent_session_ram_trim(&backend->session, keep);
338	    while (ret == AGENT_OK && keep &&
339	           backend->session.config.payload_capacity - backend->session.payload_used <
340	           CONFIG_SMART_HOME_SESSION_PAYLOAD_BYTES / 4u) {
341	        ret = agent_session_ram_trim(&backend->session, --keep);
342	    }
343	    return ret;
344	#endif
345	}
