353	#else
354	    agent_session_storage_t storage;
355	    int ret = agent_session_ram_bind(&backend->session, &storage);
356	    return ret == AGENT_OK ? storage.ops.recent(storage.context,
357	        agent_string_view("home", 4u), CONFIG_SMART_HOME_SESSION_HISTORY_TURNS, visit, context) : ret;
358	#endif
359	}
