673	int smart_home_agent_app_apply_model_config(
674	    smart_home_agent_app_t *app, const smart_home_model_config_t *config)
675	{
676	    smart_home_model_config_t resolved = {0};
677	    char error[96];
678	    int ret;
679	
680	    if (!app || !config) return AGENT_ERROR_INVALID;
681	    if (!app->agent_mutex_initialized) return AGENT_ERROR_STATE;
682	    pthread_mutex_lock(&app->agent_mutex);
683	    if (!app->agent || !app->backend) {
684	        ret = AGENT_ERROR_STATE;
685	        goto done;
686	    }
687	    if (!memchr(config->backend_id, '\0', sizeof(config->backend_id)) ||
688	        !memchr(config->host, '\0', sizeof(config->host)) ||
689	        !memchr(config->path, '\0', sizeof(config->path)) ||
690	        !memchr(config->port, '\0', sizeof(config->port)) ||
691	        !memchr(config->model, '\0', sizeof(config->model)) ||
692	        !memchr(config->api_key, '\0', sizeof(config->api_key))) {
693	        ret = AGENT_ERROR_INVALID;
694	        goto done;
695	    }
696	    ret = smart_home_model_config_validate(config, error, sizeof(error));
697	    if (ret != AGENT_OK) goto done;
698	    int manual_key = config->api_key[0] != '\0';
699	    ret = smart_home_model_config_resolve_key(config, &resolved);
700	    if (ret != AGENT_OK) goto done;
701	    ret = smart_home_agent_backend_apply(app->backend, &resolved);
702	    if (ret != AGENT_OK) goto done;
703	
704	    app->model_config = resolved;
705	    /* Keep an explicit session override; never retain a system-resolved key. */
706	    if (!manual_key && strcmp(resolved.backend_id, "custom") != 0)
707	        secure_clear(app->model_config.api_key, sizeof(app->model_config.api_key));
708	    app->system_status.model_status = AGENT_OK;
709	    app->system_status.last_error[0] = '\0';
710	    if (app->system_status.agent_status == AGENT_OK &&
711	        strcmp(resolved.backend_id, "custom") != 0)
712	        ret = smart_home_save_active_backend(resolved.backend_id);
713	
714	done:
715	    if (ret != AGENT_OK) {
716	        if (app->system_status.model_status != AGENT_OK)
717	            app->system_status.model_status = ret;
718	        smart_home_status_error(app, "Model config", ret);
719	    }
720	    secure_clear(&resolved, sizeof(resolved));
721	    pthread_mutex_unlock(&app->agent_mutex);
722	    return ret;
723	}
