725	int smart_home_agent_run(smart_home_agent_app_t *app,
726	                         const char *input, char *output, size_t output_size)
727	{
728	    agent_request_t request = {0};
729	    agent_response_t response = {0};
730	    int ret;
731	
732	    if (output && output_size) output[0] = '\0';
733	    if (!app || !input || !input[0] || !output || output_size == 0u)
734	        return AGENT_ERROR_INVALID;
735	    if (!app->agent_mutex_initialized) return AGENT_ERROR_STATE;
736	    pthread_mutex_lock(&app->agent_mutex);
737	    app->system_status.session_status = AGENT_OK;
738	    if (!app->agent) {
739	        ret = AGENT_ERROR_STATE;
740	    } else if (app->system_status.model_status != AGENT_OK) {
741	        snprintf(output, output_size,
742	                 "当前模型不可用。请在设置中选择后端并配置 API Key。");
743	        ret = app->system_status.model_status;
744	    } else {
745	        request.session_id = agent_string_view(SMART_HOME_SESSION_ID,
746	                                                sizeof(SMART_HOME_SESSION_ID) - 1u);
747	        request.input = agent_string_view(input, strlen(input));
748	        response.output = output;
749	        response.output_size = output_size;
750	        smart_home_cpu_debug_log("agent-run-start");
751	        ret = smart_home_agent_backend_prepare_turn(app->backend);
752	        if (ret == AGENT_OK) {
753	            ret = agent_run(app->agent, &request, &response);
754	            app->system_status.session_status = response.session_status;
755	        } else {
756	            app->system_status.session_status = ret;
757	        }
758	        if (ret == AGENT_OK && response.session_status != AGENT_OK)
759	            ret = response.session_status;
760	        if (ret == AGENT_OK && response.delivery_status != AGENT_OK)
761	            ret = response.delivery_status;
762	        if (ret == AGENT_OK && output[0] == '\0') {
763	            set_empty_reply_fallback(output, output_size);
764	            ret = AGENT_ERROR_MODEL_FAILED;
765	        }
766	    }
767	    pthread_mutex_unlock(&app->agent_mutex);
768	    return ret;
769	}
