777	static agent_error_t visit_tool(void *user_data, const agent_tool_t *tool)
778	{
779	    tool_visit_t *visit = user_data;
780	    char name[AGENT_MAX_NAME_BYTES + 1u];
781	    char description[AGENT_MAX_DESCRIPTION_BYTES + 1u];
782	    smart_home_tool_info_t info = {0};
783	
784	    if (tool->name.size >= sizeof(name) || tool->description.size >= sizeof(description))
785	        return AGENT_ERROR_CAPACITY;
786	    if ((tool->name.size && !tool->name.data) ||
787	        (tool->description.size && !tool->description.data)) return AGENT_ERROR_INVALID;
788	    if (tool->name.size) memcpy(name, tool->name.data, tool->name.size);
789	    name[tool->name.size] = '\0';
790	    if (tool->description.size)
791	        memcpy(description, tool->description.data, tool->description.size);
792	    description[tool->description.size] = '\0';
793	    info.name = name;
794	    info.description = description;
795	    info.group_id = smart_home_tool_group_id(tool->group);
796	    info.category_id = smart_home_tool_category_id(tool->category);
797	    info.flags = tool->flags;
798	    info.enabled = (tool->flags & AGENT_TOOL_DISABLED) == 0u;
799	    info.llm_visible = (tool->flags & (AGENT_TOOL_DISABLED | AGENT_TOOL_HIDDEN)) == 0u;
800	    info.access_allowed = info.group_id != SMART_HOME_TOOL_GROUP_LOCAL ||
801	                          local_tool_access_allowed(visit->app, name);
802	    return (agent_error_t)visit->callback(&info, visit->user_data);
