845	int smart_home_agent_app_set_local_tool_access(smart_home_agent_app_t *app,
846	                                               const char *tool_name,
847	                                               int allowed)
848	{
849	    local_tool_match_t match = {
850	        .name = tool_name,
851	        .is_local = 0,
852	    };
853	    int ret;
854	
855	    if (!app || !app->agent || !tool_name || !tool_name[0]) {
856	        if (app) {
857	            app->system_status.tools_status = AGENT_ERROR_INVALID;
858	            smart_home_status_error(app, "Tool access", AGENT_ERROR_INVALID);
859	        }
860	        return AGENT_ERROR_INVALID;
861	    }
862	
863	    if (!app->agent_mutex_initialized) return AGENT_ERROR_STATE;
864	    pthread_mutex_lock(&app->agent_mutex);
865	    ret = enumerate_tools_locked(app, match_local_tool, &match);
866	    if (ret == AGENT_OK && !match.is_local) {
867	        ret = AGENT_ERROR_NOT_SUPPORTED;
868	    }
869	    if (ret == AGENT_OK && !match.core_enabled) {
870	        ret = AGENT_ERROR_NOT_SUPPORTED;
871	    }
872	    if (ret == AGENT_OK) {
873	        int index = local_tool_access_index(app, tool_name);
874	
875	        if (index < 0) {
876	            size_t name_length = strlen(tool_name);
877	
878	            if (name_length >= SMART_HOME_LOCAL_TOOL_NAME_SIZE) {
879	                ret = AGENT_ERROR_LIMIT;
880	            } else if (app->local_tool_access_count >=
881	                       SMART_HOME_LOCAL_TOOL_ACCESS_MAX) {
882	                ret = AGENT_ERROR_LIMIT;
883	            } else {
884	                index = (int)app->local_tool_access_count++;
885	                memcpy(app->local_tool_access[index].name,
886	                       tool_name,
887	                       name_length + 1u);
888	            }
889	        }
890	
891	        if (ret == AGENT_OK && index >= 0) {
892	            app->local_tool_access[index].allowed = allowed ? 1 : 0;
893	        }
894	    }
895	    app->system_status.tools_status = ret;
896	    if (ret != AGENT_OK) {
897	        smart_home_status_error(app, "Tool access", ret);
898	    } else {
899	        app->system_status.last_error[0] = '\0';
900	    }
901	    pthread_mutex_unlock(&app->agent_mutex);
902	    return ret;
903	}
