196	static agent_error_t model_step(run_t* run, agent_context_turn_t* context,
197	                                agent_session_turn_t* session, agent_message_view_t* message)
198	{
199	    agent_context_projection_t projection;
200	    model_output_t output = {0};
201	    agent_model_sink_t sink = {collect_text, collect_call, &output};
202	    agent_error_t status, released, checked;
203	    size_t reserve, descriptors;
204	    void* memory;
205	    uint64_t now;
206	    agent_t* agent = run->agent;
207	    status = agent_size_multiply(AGENT_MAX_MODEL_TOOL_CALLS, sizeof(agent_tool_call_view_t),
208	                                 &descriptors);
209	    if (status == AGENT_OK)
210	        status =
211	            agent_size_add(descriptors, AGENT_ALIGNOF(agent_tool_call_view_t) - 1u, &descriptors);
212	    if (status == AGENT_OK)
213	        status = agent_size_add(descriptors,
214	                                AGENT_MAX_MODEL_OUTPUT_BYTES ? AGENT_MAX_MODEL_OUTPUT_BYTES : 1u,
215	                                &reserve);
216	    if (status != AGENT_OK)
217	        return status;
218	    status = agent_context_project(context, session,
219	                                   run->limits.max_tool_calls - run->summary.tool_calls, reserve,
220	                                   &projection);
221	    if (status != AGENT_OK)
222	        return status;
223	    output.run = run;
224	    output.arena = agent->scratch;
225	    output.arena.capacity -= descriptors;
226	    output.start = output.arena.used;
227	    status = agent_arena_take(&output.arena,
228	                              AGENT_MAX_MODEL_OUTPUT_BYTES ? AGENT_MAX_MODEL_OUTPUT_BYTES : 1u, 1u,
229	                              &memory);
230	    output.arguments = output.arena.used;
231	    if (status == AGENT_OK)
232	    {
233	        now = agent_runtime_now_ms(&agent->config.runtime);
234	        output.deadline = deadline_at(now, run->limits.per_model_timeout_ms, run->deadline);
235	        projection.request.deadline_ms = output.deadline;
236	        projection.request.timeout_ms = !output.deadline         ? 0u
237	                                        : output.deadline <= now ? 1u
238	                                        : output.deadline - now > UINT32_MAX
239	                                            ? UINT32_MAX
240	                                            : (uint32_t)(output.deadline - now);
241	        status = poll(run, output.deadline);
242	    }
243	    if (status == AGENT_OK)
244	    {
245	        increment(&run->summary.model_calls);
246	        increment(&agent->stats.model_calls);
247	        increment(&agent->stats.iterations);
248	        emit(run, AGENT_EVENT_MODEL_BEGIN, AGENT_OK, NULL);
249	        agent->in_callback = true;
250	        status = agent_model_dispatch(agent->model, &projection.request, &sink);
251	        agent->in_callback = false;
252	        checked = poll(run, output.deadline);
253	        if (checked != AGENT_OK)
254	            status = checked;
255	        else if (output.status != AGENT_OK)
256	            status = output.status;
257	        else if (status == AGENT_ERROR || status > AGENT_OK)
258	            status = AGENT_ERROR_MODEL_FAILED;
259	        if (status == AGENT_OK &&
260	            agent_text_validate(agent_string_view((char*)output.arena.base + output.start,
261	                                                  output.text_size)) != AGENT_OK)
262	            status = AGENT_ERROR_MODEL_PARSE;
263	        emit(run, AGENT_EVENT_MODEL_END, status, NULL);
264	    }
265	    if (output.arena.peak > agent->scratch.peak)
266	        agent->scratch.peak = output.arena.peak;
267	    released = agent_context_release(&projection);
268	    if (status == AGENT_OK)
269	        status = released;
270	    if (status == AGENT_OK)
271	        status = retain_output(&output, message);
272	    return status;
273	}
