305	static agent_error_t tool_batch(run_t* run, agent_session_turn_t* session,
306	                                const agent_message_view_t* message)
307	{
308	    size_t i, capacity, bytes;
309	    agent_error_t status;
310	    agent_t* agent = run->agent;
311	    agent_tool_observer_t observer = {tool_begin, tool_end, run};
312	    status = agent_size_add(AGENT_MAX_TOOL_OUTPUT_BYTES, 1u, &capacity);
313	    if (status == AGENT_OK)
314	        status = agent_size_multiply(message->tool_call_count, capacity, &bytes);
315	    if (status != AGENT_OK)
316	        return status;
317	    if (bytes > agent->scratch.capacity - agent->scratch.used)
318	        return AGENT_ERROR_CAPACITY;
319	    for (i = 0u; i < message->tool_call_count; ++i)
320	    {
321	        agent_tool_context_t context = {0};
322	        agent_tool_execution_t execution = {0};
323	        agent_message_view_t result = {0};
324	        void* buffer;
325	        size_t mark = agent->scratch.used;
326	        status = poll(run, run->deadline);
327	        if (status != AGENT_OK)
328	            return status;
329	        status = agent_arena_take(&agent->scratch, capacity, 1u, &buffer);
330	        if (status != AGENT_OK)
331	            return status;
332	        context.call = message->tool_calls[i];
333	        context.session_id = run->request.session_id;
334	        context.trace_id = run->request.trace_id;
335	        context.limits = &run->limits;
336	        context.cancel = &run->cancel;
337	        context.deadline_ms = run->deadline;
338	        context.request_user_data = run->request.user_data;
339	        status = agent_tool_invoke_observed(agent, &context,
340	                                            run->limits.max_tool_calls - run->summary.tool_calls,
341	                                            buffer, capacity, &execution, &observer);
342	        if (!execution.handler_called)
343	            increment(&run->summary.tool_denied);
344	        if (status == AGENT_ERROR_CANCELLED || status == AGENT_ERROR_TIMEOUT ||
345	            status == AGENT_ERROR_LIMIT || status == AGENT_ERROR_CAPACITY)
346	            return status;
347	        result.role = AGENT_MESSAGE_ROLE_TOOL;
348	        result.tool_call_id = context.call.id;
349	        result.content = execution.output;
350	        if (status != AGENT_OK)
351	        {
352	            const char* error = agent_error_str(status);
353	            size_t length = strlen(error);
354	            if (length >= capacity)
355	                return AGENT_ERROR_CAPACITY;
356	            memcpy(buffer, error, length + 1u);
357	            result.content = agent_string_view(buffer, length);
358	        }
359	        agent->scratch.used = mark + result.content.size + 1u;
360	        status = append(run, session, &result);
361	        if (status != AGENT_OK)
362	            return status;
363	    }
364	    return AGENT_OK;
365	}
