367	static bool output_safe(const agent_t* agent, const agent_request_t* request, const void* data,
368	                        size_t bytes)
369	{
370	    size_t i;
371	    const agent_string_view_t fields[] = {request->input, request->session_id, request->trace_id,
372	                                          agent->config.system_prompt};
373	    if ((!data && bytes) || bytes > UINTPTR_MAX - (uintptr_t)data ||
374	        agent_bytes_overlap(data, bytes, agent->workspace, agent->workspace_size) ||
375	        agent_bytes_overlap(data, bytes, request, sizeof(*request)) ||
376	        (request->limits &&
377	         agent_bytes_overlap(data, bytes, request->limits, sizeof(*request->limits))) ||
378	        !agent_tool_registry_buffer_safe(agent->tools, data, bytes))
379	        return false;
380	    for (i = 0u; i < sizeof(fields) / sizeof(fields[0]); ++i)
381	        if (agent_bytes_overlap(data, bytes, fields[i].data, fields[i].size))
382	            return false;
383	    if (agent->skills)
384	        for (i = 0u; i < agent->skills->count; ++i)
385	        {
386	            const agent_skill_t* skill = &agent->skills->entries[i];
387	            if (agent_bytes_overlap(data, bytes, skill->name.data, skill->name.size) ||
388	                agent_bytes_overlap(data, bytes, skill->description.data,
389	                                    skill->description.size) ||
390	                agent_bytes_overlap(data, bytes, skill->content.data, skill->content.size))
391	                return false;
392	        }
393	    if (agent->contexts)
394	        for (i = 0u; i < agent->contexts->count; ++i)
395	        {
396	            const agent_context_entry_t* entry = &agent->contexts->entries[i];
397	            if (agent_bytes_overlap(data, bytes, entry->provider.name.data,
398	                                    entry->provider.name.size) ||
399	                (entry->memory &&
400	                 agent_bytes_overlap(data, bytes, entry->key.id.data, entry->key.id.size)))
401	                return false;
402	        }
403	    return true;
404	}
