406	static void deliver(agent_response_t* response, agent_string_view_t final)
407	{
408	    size_t size = response->output_size ? response->output_size - 1u : 0u;
409	    if (size > final.size)
410	        size = final.size;
411	    while (size && size < final.size && ((unsigned char) final.data[size] & 0xc0u) == 0x80u)
412	        --size;
413	    if (size)
414	        memcpy(response->output, final.data, size);
415	    if (response->output_size)
416	        response->output[size] = '\0';
417	    response->output_written = size;
418	    response->output_required = final.size;
419	    response->output_truncated = size < final.size;
420	    response->delivery_status = response->output_truncated ? AGENT_ERROR_TRUNCATED : AGENT_OK;
421	}
