423	agent_error_t agent_run(agent_t* agent, const agent_request_t* request, agent_response_t* response)
424	{
425	    run_t run = {0};
426	    agent_session_turn_t* session = NULL;
427	    agent_context_turn_t* context = NULL;
428	    agent_string_view_t final = {0};
429	    agent_error_t status = agent_core_require_idle(agent), finished;
430	    char* output;
431	    size_t output_size;
432	    uint32_t step;
433	    uint64_t now;
434	    if (status != AGENT_OK)
435	        return status;
436	    if (!request || !response || !output_safe(agent, request, response, sizeof(*response)) ||
437	        !output_safe(agent, request, response->output, response->output_size) ||
438	        agent_bytes_overlap(response, sizeof(*response), response->output, response->output_size))
439	        return AGENT_ERROR_INVALID;
440	    /* Resetting scratch must not invalidate the request's borrowed inputs. */
441	    if (agent_bytes_overlap(request, sizeof(*request), agent->workspace, agent->workspace_size) ||
442	        agent_bytes_overlap(request->input.data, request->input.size, agent->workspace,
443	                            agent->workspace_size) ||
444	        agent_bytes_overlap(request->session_id.data, request->session_id.size, agent->workspace,
445	                            agent->workspace_size) ||
446	        agent_bytes_overlap(request->trace_id.data, request->trace_id.size, agent->workspace,
447	                            agent->workspace_size))
448	        return AGENT_ERROR_INVALID;
449	    run.agent = agent;
450	    run.request = *request;
451	    run.limits = request->limits ? *request->limits : agent->config.limits;
452	    if (!run.request.session_id.size)
453	        run.request.session_id = agent_string_view("default", 7u);
454	    output = response->output;
455	    output_size = response->output_size;
456	    memset(response, 0, sizeof(*response));
457	    response->output = output;
458	    response->output_size = output_size;
459	    if (output_size)
460	        output[0] = '\0';
461	    if (agent->state != AGENT_CORE_READY)
462	        status = AGENT_ERROR_STATE;
463	    else if (!agent->model)
464	        status = AGENT_ERROR_NOT_SUPPORTED;
465	    else if (run.request.input.size > AGENT_MAX_INPUT_BYTES ||
466	             run.request.session_id.size > AGENT_MAX_IDENTIFIER_BYTES ||
467	             run.request.trace_id.size > AGENT_MAX_IDENTIFIER_BYTES)
468	        status = AGENT_ERROR_LIMIT;
469	    else if (!run.limits.max_steps || !run.request.input.size ||
470	             agent_text_validate(run.request.input) != AGENT_OK ||
471	             agent_text_validate(run.request.session_id) != AGENT_OK ||
472	             agent_text_validate(run.request.trace_id) != AGENT_OK)
473	        status = AGENT_ERROR_INVALID;
474	    if (status != AGENT_OK)
475	    {
476	        response->stats = agent->stats;
477	        return response->status = status;
478	    }
479	    run.request.limits = &run.limits;
480	    agent_cancel_token_init(&run.cancel, &agent->config.runtime.cancel_sync);
481	    agent->state = AGENT_CORE_ACTIVE;
482	    agent->scratch.used = agent->scratch.peak = 0u;
483	    run.started = agent_runtime_now_ms(&agent->config.runtime);
484	    run.deadline = deadline_at(run.started, run.limits.timeout_ms, 0u);
485	    publish_cancel(&run, true);
486	    increment(&agent->stats.runs);
487	    emit(&run, AGENT_EVENT_TURN_BEGIN, AGENT_OK, NULL);
488	    status = poll(&run, run.deadline);
489	    if (status == AGENT_OK)
490	    {
491	        agent->in_callback = true;
492	        status = agent_session_turn_open(
493	            &session, &agent->scratch, agent->has_session_storage ? &agent->session_storage : NULL,
494	            run.request.session_id, run.request.input);
495	        agent->in_callback = false;
496	        run.session_status = status;
497	    }
498	    if (status == AGENT_OK)
499	        status = agent_context_prepare(agent, &run.request, &run.cancel, run.deadline, &context);
500	    for (step = 0u; status == AGENT_OK && step < run.limits.max_steps; ++step)
501	    {
502	        agent_message_view_t message;
503	        status = poll(&run, run.deadline);
504	        if (status == AGENT_OK)
505	            status = model_step(&run, context, session, &message);
506	        if (status != AGENT_OK)
507	            break;
508	        if (!message.tool_call_count)
509	        {
510	            run.summary.final_valid = true;
511	            final = message.content;
512	            status = append(&run, session, &message);
513	            break;
514	        }
515	        if (message.tool_call_count > run.limits.max_tool_calls - run.summary.tool_calls ||
516	            message.tool_call_count + 2u >
517	                AGENT_MAX_PROJECTED_MESSAGES - agent_session_current_count(session))
518	        {
519	            status = AGENT_ERROR_LIMIT;
520	            break;
521	        }
522	        status = append(&run, session, &message);
523	        if (status == AGENT_OK)
524	            status = tool_batch(&run, session, &message);
525	    }

