265	static void smart_home_lvgl_uv_loop(uv_loop_t *loop,
266	                                    lv_nuttx_result_t *result,
267	                                    smart_home_lvgl_t *ui)
268	{
269	    lv_nuttx_uv_t uv_info;
270	    uv_timer_t pending_timer;
271	    void *data;
272	
273	    uv_loop_init(loop);
274	    lv_memzero(&uv_info, sizeof(uv_info));
275	    uv_info.loop = loop;
276	    uv_info.disp = result->disp;
277	    uv_info.indev = result->indev;
278	#ifdef CONFIG_UINPUT_TOUCH
279	    uv_info.uindev = result->utouch_indev;
280	#endif
281	#ifdef CONFIG_LV_USE_NUTTX_MOUSE
282	    uv_info.mouse_indev = result->mouse_indev;
283	#endif
284	
285	    data = lv_nuttx_uv_init(&uv_info);
286	    if (uv_timer_init(loop, &pending_timer) == 0) {
287	        pending_timer.data = ui;
288	        uv_timer_start(&pending_timer,
289	                       smart_home_lvgl_uv_pending_cb,
290	                       0,
291	                       SMART_HOME_LVGL_QUEUE_POLL_MS);
292	    }
293	    uv_run(loop, UV_RUN_DEFAULT);
294	    lv_nuttx_uv_deinit(&data);
295	}
296	#endif
