298	int smart_home_lvgl_run(smart_home_agent_app_t *app,
299	                        const char *initial_input)
300	{
301	    lv_nuttx_dsc_t info;
302	    lv_nuttx_result_t result;
303	    smart_home_lvgl_t *ui;
304	
305	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
306	    uv_loop_t ui_loop;
307	    lv_memzero(&ui_loop, sizeof(ui_loop));
308	#endif
309	
310	    if (!app) {
311	        return AGENT_ERROR_INVALID;
312	    }
313	
314	    if (lv_is_initialized()) {
315	        return AGENT_ERROR_BUSY;
316	    }
317	
318	    smart_home_cpu_debug_log("lvgl-run-start");
319	
320	#ifdef NEED_BOARDINIT
321	    boardctl(BOARDIOC_INIT, 0);
322	#endif
323	
324	    lv_init();
325	#ifdef CONFIG_SMART_HOME_DEMO_DEBUG_LOG
326	    printf("[lvgl] lv_init done\n");
327	#endif
328	    smart_home_lvgl_style_init();
329	    lv_nuttx_dsc_init(&info);
330	
331	    info.fb_path = CONFIG_SMART_HOME_DEMO_LVGL_FB_PATH;
332	
333	#ifdef CONFIG_INPUT_TOUCHSCREEN
334	    info.input_path = SMART_HOME_TOUCH_PATH;
335	#endif
336	
337	    lv_nuttx_init(&info, &result);
338	    if (!result.disp) {
339	        smart_home_lvgl_style_deinit();
340	        lv_deinit();
341	        return AGENT_ERROR;
342	    }
343	
344	#ifdef CONFIG_INPUT_TOUCHSCREEN
345	    printf("[smart_home_lvgl] disp=%p indev=%p input=%s\n",
346	           (void *)result.disp,
347	           (void *)result.indev,
348	           SMART_HOME_TOUCH_PATH);
349	#else
350	    printf("[smart_home_lvgl] disp=%p indev=%p input=disabled\n",
351	           (void *)result.disp,
352	           (void *)result.indev);
353	#endif
354	
355	    ui = smart_home_lvgl_init(app);
356	    if (!ui) {
357	#ifdef CONFIG_SMART_HOME_DEMO_DEBUG_LOG
358	        printf("[lvgl] ui init FAILED\n");
359	#endif
360	        lv_nuttx_deinit(&result);
361	        smart_home_lvgl_style_deinit();
362	        lv_deinit();
363	        return AGENT_ERROR_NOMEM;
364	    }
365	#ifdef CONFIG_SMART_HOME_DEMO_DEBUG_LOG
366	    printf("[lvgl] ui init done\n");
367	#endif
368	
369	    smart_home_agent_app_set_observer(app, smart_home_lvgl_event_cb, ui);
370	    smart_home_lvgl_show(ui);
371	#ifdef CONFIG_SMART_HOME_DEMO_DEBUG_LOG
372	    printf("[lvgl] show done, entering run loop\n");
373	#endif
374	
375	    if (initial_input && initial_input[0]) {
376	        ui->active_tab = SMART_HOME_TAB_CHAT;
377	        lv_scr_load(ui->screen_chat);
378	        smart_home_lvgl_chat_send_text(ui, initial_input);
379	    }
380	
381	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
382	    smart_home_lvgl_uv_loop(&ui_loop, &result, ui);
383	#else
384	    smart_home_cpu_debug_log("lvgl-loop-start");
385	#ifdef CONFIG_SMART_HOME_V9_PERF_LOG
386	    uint32_t perf_frames = 0;
387	    uint32_t perf_sum_ms = 0;
388	    uint32_t perf_max_ms = 0;
389	    uint32_t perf_window = lv_tick_get();
390	#endif
391	    for (;;) {
392	        uint32_t idle;
393	#ifdef CONFIG_SMART_HOME_V9_PERF_LOG
394	        uint32_t started = lv_tick_get();
395	#endif
396	
397	        smart_home_lvgl_process_pending(ui);
398	        idle = lv_timer_handler();
399	        smart_home_lvgl_process_pending(ui);
400	#ifdef CONFIG_SMART_HOME_V9_PERF_LOG
401	        {
402	            uint32_t elapsed = lv_tick_get() - started;
403	
404	            perf_frames++;
405	            perf_sum_ms += elapsed;
406	            if (elapsed > perf_max_ms) perf_max_ms = elapsed;
407	            if (lv_tick_elaps(perf_window) >= 5000u) {
408	                /* 同一行带出用户堆快照，P01-P12 只需一份串口日志即可回填；
409	                 * mallinfo() 反映 umm 用户堆（LVGL 与业务对象所在堆）。
410	                 */
411	                struct mallinfo mem = mallinfo();
412	
413	                printf("[v9-perf] frames=%u avg_ms=%u max_ms=%u "
414	                       "heap_used=%u heap_free=%u heap_largest=%u scene=%s\n",
415	                       (unsigned)perf_frames,
416	                       (unsigned)(perf_sum_ms / (perf_frames ? perf_frames : 1)),
417	                       (unsigned)perf_max_ms,
418	                       (unsigned)mem.uordblks, (unsigned)mem.fordblks,
419	                       (unsigned)mem.mxordblk, v9_perf_scene(ui));
420	                perf_frames = 0;
421	                perf_sum_ms = 0;
422	                perf_max_ms = 0;
423	                perf_window = lv_tick_get();
424	            }
425	        }
426	#endif
427	        if (idle == 0 || idle > SMART_HOME_LVGL_QUEUE_POLL_MS) {
428	            idle = SMART_HOME_LVGL_QUEUE_POLL_MS;
429	        }
430	        usleep((idle ? idle : 1) * 1000);
431	    }
432	#endif
433	#ifdef CONFIG_SMART_HOME_DEMO_DEBUG_LOG
434	    printf("[lvgl] run loop exited\n");
435	#endif
436	
437	    smart_home_lvgl_deinit(ui);
438	    lv_nuttx_deinit(&result);
439	    smart_home_lvgl_style_deinit();
440	    lv_deinit();
441	    return AGENT_OK;
442	}
